\version "2.27.2"
% automatically converted by musicxml2ly from 61j-Lyrics-Elisions.xml
\pointAndClickOff

\header {
  texidoc = "Multiple lyrics syllables assigned to a single note are implemented
    either using a space in the <text> child of <lyric>, or by using <elision>.

    The first note has a single syllable, the second note has two syllables
    separated by a space, the third has two syllables with <elision> set to an
    undertie, and the fourth has three syllables (the first and third one in
    red, and the second one being in italic and overriding the color with blue),
    with a green undertie between the first and second syllable and an empty
    <elision> element between the second and third syllable, causing an
    application-specific elision glyph.

    None of the <lyric> elements has the ‘number’ attribute set."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c'' {
  \clef "treble" \time 4/4 \key c \major c1 | % 1
  c1 | % 2
  c1 | % 3
  c1 \bar "|."
}

PartPOneVoiceOneLyricsOne = \lyricmode {
  \set ignoreMelismata = ##t
  \set includeGraceNotes = ##t
  a "b c" "d~e" \markup \concat { \with-color "#FF0000" f \with-color "#00FF00"
    "‿" \italic \with-color "#0000FF" "g " \with-color "#FF0000" h }
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
        \new Lyrics \lyricsto "PartPOneVoiceOne" {
          \PartPOneVoiceOneLyricsOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
